#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin >> n;
    string s; cin >> s;

    vector<int> kpos, vpos, opos;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'V') vpos.push_back(i);
        else if (s[i] == 'K') kpos.push_back(i);
        else opos.push_back(i);
    }

    int nk = (int)kpos.size();
    int nv = (int)vpos.size();
    int no = (int)opos.size();

    const int INF = 1e9;
    // Dimensions: 2 x (nk+1) x (nv+1) x (no+1)
    vector<vector<vector<vector<int>>>> dp(2,
        vector<vector<vector<int>>>(nk + 1,
            vector<vector<int>>(nv + 1,
                vector<int>(no + 1, INF)
            )
        )
    );

    dp[0][0][0][0] = 0;

    for (int k = 0; k <= nk; k++) {
        for (int v = 0; v <= nv; v++) {
            for (int o = 0; o <= no; o++) {
                for (int h = 0; h < 2; h++) {
                    int val = dp[h][k][v][o];
                    if (val == INF) continue;
                    // Try to pick 'K'
                    if (k < nk && h == 0) {
                        int cost = val + max(kpos[k] - v, 0) + max(kpos[k] - o, 0);
                        if (cost < dp[0][k + 1][v][o]) {
                            dp[0][k + 1][v][o] = cost;
                        }
                    }
                    // Try to pick 'V'
                    if (v < nv) {
                        int cost = val + max(vpos[v] - k, 0) + max(vpos[v] - o, 0);
                        if (cost < dp[1][k][v + 1][o]) {
                            dp[1][k][v + 1][o] = cost;
                        }
                    }
                    // Try to pick 'O'
                    if (o < no) {
                        int cost = val + max(opos[o] - v, 0) + max(opos[o] - k, 0);
                        if (cost < dp[0][k][v][o + 1]) {
                            dp[0][k][v][o + 1] = cost;
                        }
                    }
                }
            }
        }
    }

    int answer = min(dp[0][nk][nv][no], dp[1][nk][nv][no]);
    cout << answer << "\n";

    return 0;
}
